NEW_FILES = {'data/textos/sistema_solar_examen.tsv': '# Examen de COMPRENSION del texto del sistema solar (parche-92). Informativo. Las frases son las de data/textos/sistema_solar.txt; las preguntas NO estan en el texto tal cual.\nSEMILLA: conocimiento de fabrica (colores...) como en scripts.think\nU: El Sol es una estrella.\t\nU: El Sol está en el centro del Sistema Solar.\t\nU: Los planetas giran alrededor del Sol.\t\nU: Mercurio es el planeta más cercano al Sol.\t\nU: Venus es el segundo planeta.\t\nU: La Tierra es el tercer planeta y tiene una luna.\t\nU: La Luna gira alrededor de la Tierra.\t\nU: Marte es un planeta rojo.\t\nU: Marte tiene dos lunas.\t\nU: Júpiter es el planeta más grande.\t\nU: Júpiter es un gigante gaseoso.\t\nU: Saturno tiene anillos.\t\nU: Urano y Neptuno son planetas helados.\t\nU: Plutón es un planeta enano.\t\nU: Los asteroides son rocas pequeñas.\t\nU: Los cometas están hechos de hielo y polvo.\t\nU: ¿Qué es el Sol?\testrella\nU: ¿Dónde está el Sol?\tcentro\nU: ¿Qué gira alrededor del Sol?\tplanetas\nU: ¿Qué es Mercurio?\tplaneta\nU: ¿Cuál es el planeta más cercano al Sol?\tMercurio\nU: ¿Cuál es el segundo planeta?\tVenus\nU: ¿Cuál es el tercer planeta?\tTierra\nU: ¿Cuántas lunas tiene Marte?\tdos\nU: ¿Qué tiene la Tierra?\tluna\nU: ¿Alrededor de qué gira la Luna?\tTierra\nU: ¿De qué color es Marte?\trojo\nU: ¿Cuál es el planeta más grande?\tJúpiter\nU: ¿Qué es Júpiter?\tgigante\nU: ¿Qué tiene Saturno?\tanillos\nU: ¿Qué planetas son helados?\tUrano\nU: ¿Cómo es Neptuno?\thelado\nU: ¿Qué es Plutón?\tenano\nU: ¿Qué son los asteroides?\trocas\nU: ¿De qué están hechos los cometas?\thielo\nU: ¿Gira la Tierra alrededor del Sol?\tSí\nU: ¿Es la Tierra un planeta?\tSí\nU: ¿Es Plutón un planeta?\tSí\nU: ¿Tiene Marte tres lunas?\tNo\nU: ¿Qué sabes de Saturno?\tanillos\nU: ¿Es Marte un planeta rojo?\tSí\n', 'tests/test_parche93.py': '"""parche-93: superlativos, ordinales, adjetivos en plural y preguntas sobre textos."""\nimport os\nimport tempfile\n\nfrom src.language.extract import triples_full\nfrom src.language.qa import QA\nfrom src.memory.store import MemoryStore\n\n\ndef _tree(forms, rows):\n    return [(f, r[0], r[1], r[2], r[3]) for f, r in zip(forms, rows)]\n\n\ndef test_superlativo_y_ordinal_como_hechos_propios():\n    t = _tree("Mercurio es el planeta más cercano a el Sol .".split(),\n              [("PROPN", 4, "nsubj", "mercurio"), ("AUX", 4, "cop", "ser"), ("DET", 4, "det", "el"), ("NOUN", 0, "root", "planeta"), ("ADV", 6, "advmod", "mas"),\n               ("ADJ", 4, "amod", "cercano"), ("ADP", 9, "case", "a"), ("DET", 9, "det", "el"), ("PROPN", 6, "nmod", "sol"), ("PUNCT", 4, "punct", ".")])\n    got = {(x["s"], x["p"], x["o"]) for x in triples_full(t)}\n    assert ("mercurio", "es", "planeta") in got and ("mercurio", "ser_el_mas_cercano", "planeta_al_sol") in got and ("mercurio", "ser", "cercano") not in got\n    t2 = _tree("Venus es el segundo planeta .".split(),\n               [("PROPN", 5, "nsubj", "venus"), ("AUX", 5, "cop", "ser"), ("DET", 5, "det", "el"), ("ADJ", 5, "amod", "segundo"), ("NOUN", 0, "root", "planeta"), ("PUNCT", 5, "punct", ".")])\n    assert ("venus", "ser_el_segundo", "planeta") in {(x["s"], x["p"], x["o"]) for x in triples_full(t2)}\n\n\ndef test_adjetivo_plural_a_singular():\n    t = _tree("Urano y Neptuno son planetas helados .".split(),\n              [("PROPN", 5, "nsubj", "urano"), ("CCONJ", 3, "cc", "y"), ("PROPN", 1, "conj", "neptuno"), ("AUX", 5, "cop", "ser"), ("NOUN", 0, "root", "planeta"),\n               ("ADJ", 5, "amod", "helado"), ("PUNCT", 5, "punct", ".")])\n    got = {(x["s"], x["p"], x["o"]) for x in triples_full(t)}\n    assert ("urano", "ser", "helado") in got and ("neptuno", "ser", "helado") in got\n\n\ndef _qa(facts):\n    mem = MemoryStore(os.path.join(tempfile.mkdtemp(), "m.json"))\n    for f in facts:\n        mem.add_fact(f)\n    return QA(mem, lambda s: [], lambda fs: [])\n\n\ndef test_preguntas_de_texto():\n    qa = _qa([("MERCURIO", "es", "planeta"), ("MERCURIO", "ser_el_mas_cercano", "planeta_al_sol"), ("TIERRA", "ser_el_tercero", "planeta"),\n              ("URANO", "es", "planeta"), ("URANO", "ser", "helado"), ("NEPTUNO", "es", "planeta"), ("NEPTUNO", "ser", "helado"),\n              ("COMETAS", "hecho_de", "hielo"), ("COMETAS", "hecho_de", "polvo")])\n    assert "Mercurio" in qa.special("¿Cuál es el planeta más cercano al Sol?")\n    assert "Tierra" in qa.special("¿Cuál es el tercer planeta?")\n    assert "Tierra" in qa.special("¿Qué planeta es el tercero?")\n    assert qa.special("¿Qué planetas son helados?").startswith("Urano y Neptuno son planetas helados")\n    r = qa.special("¿De qué están hechos los cometas?")\n    assert "hielo" in r and "polvo" in r\n    assert qa.special("¿Cuál es el planeta más grande?") == "No lo sé."\n    assert qa.special("¿Qué hora es?") is None\n\n\ndef test_concordancia_al_reutilizar_plantillas():\n    assert QA._agree("{s} giran alrededor de {o}", "Urano") == "{s} gira alrededor de {o}"\n    assert QA._agree("{s} es {o}", "Los asteroides") == "{s} son {o}"\n    assert QA._agree("{s} vive en {o}", "Pedro") == "{s} vive en {o}"\n    assert QA._agree("{s} viven en {o}", "Pedro y Marta") == "{s} viven en {o}"\n'}

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-93 instalado. Copias en {bk}" if plan else "parche-93: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

